llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Posaconazole, a large lipophilic azole with a triazole heterocycle, has reported oral bioavailability >90% in humans; other adult records give 50–75%, supporting high F for the query's azole-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Atazanavir, a large HIV protease inhibitor with multiple aromatic/heteroaromatic and tert-butyl groups, has oral bioavailability of 68% (57–80%) in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Perindopril, a carboxylic-acid-containing drug, has absolute oral bioavailability of 66% in humans, showing that the query's carboxylic acid does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Ursodeoxycholic acid, a steroid carboxylic acid structurally closest to the query's fused-ring acid scaffold, has systemic availability of 78–87% in cirrhotic patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Cilomilast, a lipophilic carboxylic acid with ether and cycloalkyl groups, has absolute bioavailability of 96% (92–102%) in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "KNI-272, a large peptidomimetic HIV protease inhibitor, has absolute oral bioavailability of 33.5% in fasting patients, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pentazocine, a smaller lipophilic opioid with a basic amine, has absolute oral bioavailability of only 18% in healthy subjects, providing a contradictory low-F anchor; its lower transfer score and smaller scaffold limit its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Weighted evidence from high-transfer analogues (posaconazole, atazanavir, perindopril, UDCA, cilomilast, KNI-272) predominantly shows absolute oral bioavailability ≥20%, often 50–100%; the only low-F analogue (pentazocine) has lower transferability and a less query-relevant scaffold. Therefore predict high.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "Bioavailability of azole/lipophilic drugs is formulation- and food-dependent; pediatric suspension data for posaconazole show F <20%.",
    "First-pass metabolism and transporter effects for the query's primary amine/carboxylic acid combination are unknown.",
    "Exact structural similarity to evidence molecules is limited; transfer scores are applicability estimates, not direct measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

